def readable(value):
    """Normalize compact price/year notation without changing identifiers or URLs."""
    if isinstance(value, list):
        return [readable(v) for v in value]
    if isinstance(value, dict):
        return {k: (v if k in {'id','slug','iso','url','source','start','end','checked','status','variant_key'} else readable(v)) for k,v in value.items()}
    if not isinstance(value, str) or value.startswith('http'):
        return value
    value = re.sub(r'([А-Яа-яЁё])([A-Za-z0-9])', r'\1 \2', value)
    value = re.sub(r'([A-Za-z0-9])([А-Яа-яЁё])', r'\1 \2', value)
    value = re.sub(r'([,;:])(?=[A-Za-zА-Яа-яЁё0-9])', r'\1 ', value)
    return value


